SELECT  coalesce(json_agg("root" ORDER BY "root.pg.id" ASC NULLS LAST), '[]' ) AS "root" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.base"."name" AS "name", "_root.ar.root.articles"."articles" AS "articles"       ) AS "_e"      ) ) AS "root", "_root.base"."id" AS "root.pg.id" FROM  (SELECT  *  FROM "public"."author"  WHERE ('true')   ORDER BY "id" ASC NULLS LAST  ) AS "_root.base" LEFT OUTER JOIN LATERAL (SELECT  coalesce(json_agg("articles" ORDER BY "root.ar.root.articles.pg.published_at" DESC NULLS FIRST), '[]' ) AS "articles" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.articles.base"."title" AS "title", "_root.ar.root.articles.ar.articles.comments"."comments" AS "comments", "_root.ar.root.articles.or.author"."author" AS "author"       ) AS "_e"      ) ) AS "articles", "_root.ar.root.articles.base"."published_at" AS "root.ar.root.articles.pg.published_at" FROM  (SELECT  *  FROM "public"."article"  WHERE (("_root.base"."id") = ("author_id"))   ORDER BY "published_at" DESC NULLS FIRST  ) AS "_root.ar.root.articles.base" LEFT OUTER JOIN LATERAL (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.articles.or.author.base"."name" AS "name"       ) AS "_e"      ) ) AS "author" FROM  (SELECT  *  FROM "public"."author"  WHERE (("_root.ar.root.articles.base"."author_id") = ("id"))    LIMIT 1 ) AS "_root.ar.root.articles.or.author.base"      ) AS "_root.ar.root.articles.or.author" ON ('true') LEFT OUTER JOIN LATERAL (SELECT  coalesce(json_agg("comments" ORDER BY "root.ar.root.articles.ar.articles.comments.pg.id" DESC NULLS FIRST), '[]' ) AS "comments" FROM  (SELECT  row_to_json((SELECT  "_e"  FROM  (SELECT  "_root.ar.root.articles.ar.articles.comments.base"."body" AS "body"       ) AS "_e"      ) ) AS "comments", "_root.ar.root.articles.ar.articles.comments.base"."id" AS "root.ar.root.articles.ar.articles.comments.pg.id" FROM  (SELECT  *  FROM "public"."comment"  WHERE (("_root.ar.root.articles.base"."id") = ("article_id"))   ORDER BY "id" DESC NULLS FIRST LIMIT 1 ) AS "_root.ar.root.articles.ar.articles.comments.base"    ORDER BY "root.ar.root.articles.ar.articles.comments.pg.id" DESC NULLS FIRST  ) AS "_root.ar.root.articles.ar.articles.comments"      ) AS "_root.ar.root.articles.ar.articles.comments" ON ('true')    ORDER BY "root.ar.root.articles.pg.published_at" DESC NULLS FIRST  ) AS "_root.ar.root.articles"      ) AS "_root.ar.root.articles" ON ('true')    ORDER BY "root.pg.id" ASC NULLS LAST  ) AS "_root"      
